{
  "findings": [
    {
      "ref": "[D522]",
      "area": "contact",
      "claim": "A parent should know that live, unmoderated chat is possible between users in the console and PC versions of Fortnite: Battle Royale.",
      "stance": "risk",
      "quote": "Live, unmoderated chat is possible between users in the console and PC versions of Fortnite: Battle Royale. Options include voice chat and on-screen text chat. This exposes players to random strangers and the likelihood of profanity."
    },
    {
      "ref": "[D522]",
      "area": "contact",
      "claim": "A parent can turn off voice chat in Fortnite: Battle Royale through the Settings menu.",
      "stance": "mitigation",
      "quote": "Open the Settings menu in the top right of the main Fortnite page by selecting the three bars, then the cog icon. Choose the Audio tab at the top of the screen. From there, you can adjust several audio features, including voice chat. Turn the setting from on to off by tapping the arrows."
    },
    {
      "ref": "[D522]",
      "area": "money",
      "claim": "Fortnite pushes in-app purchases through its Battle Pass system and seasonal content updates.",
      "stance": "risk",
      "quote": "You'll begin to see clues to the updates during the current season, usually to encourage players to purchase the next season's Battle Pass."
    },
    {
      "ref": "[D522]",
      "area": "money",
      "claim": "Fortnite offers a free-to-play model but relies on in-app purchase fees, specifically related to platform policies.",
      "stance": "neutral",
      "quote": "The one place you can't play it is on iPhones, since Epic Games launched a very public battle against the Apple App Store over the way Apple collects in-app purchase fees—money Epic relies on, as it offers Fortnite: Battle Royale for free."
    },
    {
      "ref": "[D522]",
      "area": "content",
      "claim": "Reviewers report that Fortnite Live Events include concerts and promotional trailers that attract millions of viewers.",
      "stance": "neutral",
      "quote": "The platform's live events, which are often tied to a feature in the game, can attract tens of millions of viewers (not just players) around the world. Some of the most popular events include concerts, such as ones by Marshmello, Travis Scott, and Diplo, as well as in-game promotional launches, such as director J.J. Abrams' release of an exclusive Star Wars: The Rise of Skywalker trailer in advance of the movie."
    }
  ]
}
